try:
    from ortools.sat.python import cp_model
    print("ortools available")
except ImportError:
    print("ortools not available")

def solve():
    N = 14
    x = [-1] * N
    d = [-1] * (N - 1)

    x[6] = 3
    x[12] = 6
    d[3] = 10
    d[11] = 2

    used_x = [False] * N
    used_d = [False] * N

    used_x[3] = True
    used_x[6] = True
    used_d[10] = True
    used_d[2] = True

    def backtrack(idx):
        if idx == N:
            return True

        if x[idx] != -1:
            if idx > 0:
                diff = abs(x[idx] - x[idx-1])
                if d[idx-1] != -1:
                    if d[idx-1] != diff:
                        return False
                else:
                    if used_d[diff] or diff == 0:
                        return False
                    d[idx-1] = diff
                    used_d[diff] = True
                    if backtrack(idx + 1):
                        return True
                    used_d[diff] = False
                    d[idx-1] = -1
                    return False
            if backtrack(idx + 1):
                return True
            return False

        # Try all possible values for x[idx]
        for val in range(N):
            if not used_x[val]:
                if idx > 0:
                    diff = abs(val - x[idx-1])
                    if diff == 0:
                        continue
                    if d[idx-1] != -1:
                        if d[idx-1] != diff:
                            continue
                    else:
                        if used_d[diff]:
                            continue

                x[idx] = val
                used_x[val] = True
                if idx > 0 and d[idx-1] == -1:
                    d[idx-1] = diff
                    used_d[diff] = True

                if backtrack(idx + 1):
                    return True

                if idx > 0 and d[idx-1] == diff:
                    d[idx-1] = -1
                    used_d[diff] = False
                used_x[val] = False
                x[idx] = -1

        return False

    if backtrack(0):
        print("SAT")
        print(x)
    else:
        print("UNSAT")

solve()
